<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { scenarioContextHref } from './scenario-context'
import type { CatalogEntry, DiscoverySource } from './discovery'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const sources=ref<DiscoverySource[]>([]),files=ref<CatalogEntry[]>([]),error=ref(''),loading=ref(false);const controller=new AbortController()
async function load(){loading.value=true;error.value='';try{const [a,b]=await Promise.all([request<{items:DiscoverySource[]}>(workspacePath(props.workspace.slug)+'/discovery/sources',{signal:controller.signal}),request<{items:CatalogEntry[]}>(workspacePath(props.workspace.slug)+'/catalog?kind=file',{signal:controller.signal})]);sources.value=a.items.filter(s=>s.provider==='local_files');files.value=b.items}catch(e){if(!controller.signal.aborted){if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=describeError(e)}}finally{loading.value=false}}
function evidence(file:CatalogEntry){return file.metadata.fileEvidence as {mediaType?:string;sizeBytes?:number;contentDigest?:string;scope?:string;fields?:{name:string;type:string;hits?:{ruleKey:string;ruleVersion:number;category:string;method:string;matchCount:number;scannedCount:number}[]}[];locations?:{unit:string;index:number;ruleKey:string;ruleVersion:number;category:string;matchCount:number}[];coverage?:{status:string;warnings?:string[]}}|undefined}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template><section class="file-discovery"><div class="panel-heading"><div><h2>受控文件接入</h2><p>客户侧采集器仅扫描SCARLET_FILE_ROOT内已授权相对目录，平台只接收文件结构、识别统计和证据摘要，不接收正文。</p></div><a class="button button-primary" :href="scenarioContextHref(workspace.slug,'discovery')">配置文件发现来源</a></div><p v-if="error" class="message message-error" role="alert">{{error}}</p><section class="panel"><div class="panel-heading"><div><h3>已登记文件来源 · {{sources.length}}</h3><p>来源provider选择local_files，数据库项填写逻辑文件集别名；范围填写“.”或相对目录。绝对路径只在客户侧环境配置。</p></div><button class="button" :disabled="loading" @click="load">刷新</button></div><p v-if="loading" class="message" role="status">正在读取文件接入…</p><p v-else-if="!sources.length" class="message">尚未登记文件来源。先配置来源并部署客户侧采集器，再运行采集。</p><ul v-else><li v-for="source in sources" :key="source.id"><strong>{{source.source}}</strong> · {{source.database}} · {{source.scopes.join(', ')||'.'}}<small>{{source.latestRun?'最近观察 '+formatDate(source.latestRun.observedAt):'尚未收到采集结果'}} · {{source.enabled?'已启用':'已暂停'}}</small></li></ul></section><section class="panel"><div class="panel-heading"><div><h3>已观察文件资产</h3><p>当前目录API返回范围内的文件记录。完整分页与检索请在业务资产目录中选择“文件”。</p></div><a class="button" :href="scenarioContextHref(workspace.slug,'asset-catalog')">查看资产目录</a></div><p v-if="!loading&&!files.length" class="message">尚无文件观察记录。未采集、跳过或不支持的内容属于覆盖缺口。</p><div v-else class="table-wrap"><table><thead><tr><th>文件 / 来源</th><th>格式 / 大小</th><th>采集覆盖</th><th>观察</th></tr></thead><tbody><tr v-for="file in files" :key="file.id"><th scope="row"><a :href="scenarioContextHref(workspace.slug,'classification/'+file.assetId,{assetId:String(file.assetId)})">{{file.name}}</a><small>{{file.source}} · {{file.sourceRef}}</small></th><td>{{evidence(file)?.mediaType||'未知格式'}}<small>{{evidence(file)?.sizeBytes??'未知'}} bytes</small></td><td>{{evidence(file)?.coverage?.status||'待核对'}}<small>{{evidence(file)?.coverage?.warnings?.map(w=>w==='ocr_requires_review'?'OCR结果需人工核对':w).join('；')}}</small><details><summary>识别命中与位置证据</summary><p>授权目录 {{evidence(file)?.scope||'未记录'}}；仅保留匿名文件名与源端HMAC引用，不上传原路径或正文。</p><ul><li v-for="(field,index) in evidence(file)?.fields||[]" :key="index">{{field.name}} · {{field.type}}<span v-for="(hit,i) in field.hits||[]" :key="i" class="file-hit">{{hit.ruleKey}} v{{hit.ruleVersion}} · {{hit.category}} · {{hit.matchCount}}/{{hit.scannedCount}} · {{hit.method}}</span></li></ul><p v-if="!evidence(file)?.fields?.some(f=>f.hits?.length)">当前结构没有已记录命中，不代表全文无敏感数据。</p><ul><li v-for="(location,index) in (evidence(file)?.locations||[]).slice(0,50)" :key="index">{{location.unit}} #{{location.index}} · {{location.ruleKey}} v{{location.ruleVersion}} · {{location.category}} · {{location.matchCount}}次</li></ul><p v-if="(evidence(file)?.locations?.length||0)>50">此处显示前50条位置，完整来源快照可在资产目录核对。</p></details></td><td>{{formatDate(file.observedAt)}}<small>{{file.current?'当前来源观察':'历史观察，需新采集核对'}}</small></td></tr></tbody></table></div></section></section></template>
<style scoped>.file-discovery{display:grid;gap:18px}.file-discovery>.panel-heading{padding:0}.file-discovery h2{font-size:18px}.file-discovery h3{font-size:15px}.file-discovery p{font-size:12px;color:var(--secondary);line-height:1.8}.file-discovery ul{list-style:none;padding:0 18px;margin:0}.file-discovery li{padding:14px 0;border-bottom:1px solid var(--line);font-size:12px}.file-discovery small{display:block;font-size:11px;font-weight:400;color:var(--secondary);margin-top:5px;overflow-wrap:anywhere}.file-discovery table{min-width:700px;width:100%;border-collapse:collapse}.file-discovery th,.file-discovery td{padding:13px;text-align:left;font-size:12px;vertical-align:top;border-bottom:1px solid var(--line)}.file-discovery summary{cursor:pointer;color:var(--accent)}.file-discovery details{max-width:400px;margin-top:8px}.file-discovery details ul{padding:0}.file-hit{display:block;color:var(--secondary);margin-top:5px}.file-discovery a{color:var(--accent)}</style>
